//! The embedded mark: one raw RGBA8 frame per daemon state.
//!
//! The GUI carries pixels rather than a PNG so it needs no image decoder, at build time or
//! at run time: `tray_icon::Icon::from_rgba` and `egui::IconData` both take exactly this
//! layout. Generated by `scripts/make-icons.py`, whose `--check` fails on a stale asset.

/// The mark's edge in pixels; every frame here holds `SIDE * SIDE * 4` bytes.
pub const SIDE: u32 = 64;

/// Daemon up, interactive mode on.
pub const OK: &[u8] = include_bytes!("../assets/tray-ok.rgba");

/// Daemon up, interactive mode off.
pub const WARNING: &[u8] = include_bytes!("../assets/tray-warning.rgba");

/// Daemon stopped.
pub const ALERT: &[u8] = include_bytes!("../assets/tray-alert.rgba");
